fn solve(input: Vec<i8>) -> Vec<&'static str> {
    let t = input[0] as usize;
    let mut result = Vec::with_capacity(t);
    
    for i in 1..=t {
        let n = input[i] as i32; // Convert to i32 for easier calculations
        
        match n {
            1 => result.push("FastestFinger"),
            2 => result.push("Ashishgup"),
            _ => {
                // Check if n is a power of two
                if n.is_power_of_two() {
                    result.push("FastestFinger");
                } else if n % 4 != 2 {
                    result.push("Ashishgup");
                } else {
                    // n % 4 == 2
                    let p = n / 2;
                    
                    // Check if p is "limited-prime" (which is just checking if it's prime)
                    if p <= 1 {
                        result.push("Ashishgup");
                    } else if p == 2 {
                        result.push("FastestFinger");
                    } else if p % 2 == 0 {
                        // Even numbers > 2 are not prime
                        result.push("Ashishgup");
                    } else {
                        // Check if odd p is prime
                        let mut is_prime = true;
                        let limit = (p as f64).sqrt() as i32;
                        
                        for divisor in 3..=limit {
                            if divisor % 2 == 1 && p % divisor == 0 {
                                is_prime = false;
                                break;
                            }
                        }
                        
                        if is_prime {
                            result.push("FastestFinger");
                        } else {
                            result.push("Ashishgup");
                        }
                    }
                }
            }
        }
    }
    
    result
}